import{_ as o,o as a,c as r,a2 as i}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Instruções de Versão e Manutenção de Documentos","description":"","frontmatter":{},"headers":[],"relativePath":"pt/99-文档版本与维护说明.md","filePath":"pt/99-文档版本与维护说明.md","lastUpdated":1789183869000}'),d={name:"pt/99-文档版本与维护说明.md"};function s(t,e,n,c,u,m){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="instrucoes-de-versao-e-manutencao-de-documentos" tabindex="-1">Instruções de Versão e Manutenção de Documentos <a class="header-anchor" href="#instrucoes-de-versao-e-manutencao-de-documentos" aria-label="Permalink to &quot;Instruções de Versão e Manutenção de Documentos&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do documento</td><td>99</td></tr><tr><td>Módulo</td><td>Apêndices e Materiais de Referência</td></tr><tr><td>Palavras-chave principais</td><td>gerenciamento de versão, instruções de manutenção, normas de documentos, registro de atualizações, manutenção de configurações</td></tr></tbody></table><h2 id="_1-visao-geral-do-sistema-de-documentos" tabindex="-1">1. Visão Geral do Sistema de Documentos <a class="header-anchor" href="#_1-visao-geral-do-sistema-de-documentos" aria-label="Permalink to &quot;1. Visão Geral do Sistema de Documentos&quot;">​</a></h2><p>O sistema de configurações da Civilização de Simbiose de Âncora é composto por 100 documentos Markdown, numerados de 00 a 99, divididos em dez módulos, com 10 documentos em cada módulo. O sistema de documentos adota o SPEC.md (Normas de Geração de Documentos) como restrição rigorosa, o 00-Visão Geral do Universo de Hengyuanzhou como diretriz geral, os documentos de cada módulo se expandem detalhadamente a partir de diferentes dimensões, e finalmente os documentos de apêndice 90-99 realizam indexação, compilação e organização. Todo o sistema de documentos constitui um banco de conhecimento de configurações completo, logicamente autoconsistente, hierárquico e mutuamente referenciado.</p><p>O design do sistema de documentos segue três princípios: &quot;modular, estruturado, expansível&quot;. Modular significa que cada documento se concentra em um tema específico e é independente e completo; estruturado significa que todos os documentos seguem normas de formato unificadas, facilitando a leitura e recuperação; expansível significa que o sistema de documentos reserva espaço suficiente para expansão, podendo melhorar continuamente as configurações por meio da revisão de documentos existentes e da adição de novos conteúdos.</p><h2 id="_2-regras-de-numeracao-de-versao" tabindex="-1">2. Regras de Numeração de Versão <a class="header-anchor" href="#_2-regras-de-numeracao-de-versao" aria-label="Permalink to &quot;2. Regras de Numeração de Versão&quot;">​</a></h2><p>O sistema de documentos adota a regra de numeração de versão de três níveis: &quot;número de versão principal.número de versão secundária.número de revisão&quot;:</p><table tabindex="0"><thead><tr><th>Nível de Versão</th><th>Regra de Numeração</th><th>Condição de Disparo</th><th>Exemplo</th></tr></thead><tbody><tr><td>Número de versão principal</td><td>Incrementa a partir de 1</td><td>Ajuste estrutural importante no sistema de documentos, como redivisão de módulos, alteração de configurações centrais</td><td>v1.0 → v2.0</td></tr><tr><td>Número de versão secundária</td><td>Incrementa a partir de 0</td><td>Revisão substancial do conteúdo central de um documento, ou adição de conteúdo de configuração importante</td><td>v1.0 → v1.1</td></tr><tr><td>Número de revisão</td><td>Incrementa a partir de 0</td><td>Correção de texto, ajuste de formato, unificação de terminologia e outras alterações não substanciais</td><td>v1.0 → v1.0.1</td></tr></tbody></table><p>A versão geral do sistema de documentos atual é v1.0, ou seja, a primeira versão de lançamento completo. Cada documento registra seu próprio número de versão em seu bloco de informações do documento, e o número de versão geral do sistema de documentos é registrado de forma unificada neste documento.</p><h2 id="_3-revisao-das-normas-de-formato-de-documentos" tabindex="-1">3. Revisão das Normas de Formato de Documentos <a class="header-anchor" href="#_3-revisao-das-normas-de-formato-de-documentos" aria-label="Permalink to &quot;3. Revisão das Normas de Formato de Documentos&quot;">​</a></h2><p>Todos os documentos devem seguir as seguintes normas de formato unificadas (normas detalhadas consulte o SPEC.md):</p><h3 id="_3-1-nomenclatura-de-arquivos" tabindex="-1">3.1 Nomenclatura de Arquivos <a class="header-anchor" href="#_3-1-nomenclatura-de-arquivos" aria-label="Permalink to &quot;3.1 Nomenclatura de Arquivos&quot;">​</a></h3><p>O formato do nome do arquivo é <code>XX-título do documento.md</code>, onde XX é o número de dois dígitos de 00 a 99, o título está em chinês, sem espaços.</p><h3 id="_3-2-estrutura-do-documento" tabindex="-1">3.2 Estrutura do Documento <a class="header-anchor" href="#_3-2-estrutura-do-documento" aria-label="Permalink to &quot;3.2 Estrutura do Documento&quot;">​</a></h3><p>Cada documento deve conter os seguintes elementos estruturais:</p><ol><li><strong>Título de primeiro nível</strong>: Título do documento (consistente com o nome do arquivo)</li><li><strong>Bloco de informações do documento</strong>: Tabela com número, módulo, palavras-chave principais (3-5)</li><li><strong>Texto principal</strong>: Pelo menos 3 capítulos com títulos de segundo nível, usando elementos estruturados como listas e tabelas</li><li><strong>Conclusão</strong>: Parágrafo de resumo breve</li><li><strong>Documentos relacionados</strong>: Listar 2-3 números e nomes de documentos relacionados</li></ol><h3 id="_3-3-requisito-de-contagem-de-palavras" tabindex="-1">3.3 Requisito de Contagem de Palavras <a class="header-anchor" href="#_3-3-requisito-de-contagem-de-palavras" aria-label="Permalink to &quot;3.3 Requisito de Contagem de Palavras&quot;">​</a></h3><p>O texto principal de cada documento não deve ter menos de 800 caracteres (excluindo título e metadados).</p><h3 id="_3-4-estilo-de-escrita" tabindex="-1">3.4 Estilo de Escrita <a class="header-anchor" href="#_3-4-estilo-de-escrita" aria-label="Permalink to &quot;3.4 Estilo de Escrita&quot;">​</a></h3><ul><li>Estilo de documento de configurações sério e sistemático, semelhante a enciclopédia/coletânea de configurações</li><li>Usar terminologia unificada como &quot;Hengyuanzhou&quot;, &quot;âncora&quot;, &quot;simbiose&quot;</li><li>As novas configurações complementares devem ser logicamente autoconsistentes com as configurações existentes, em conformidade com o princípio de &quot;baseado na realidade, atualização de leis&quot;</li></ul><h2 id="_4-organizacao-e-responsabilidades-de-manutencao" tabindex="-1">4. Organização e Responsabilidades de Manutenção <a class="header-anchor" href="#_4-organizacao-e-responsabilidades-de-manutencao" aria-label="Permalink to &quot;4. Organização e Responsabilidades de Manutenção&quot;">​</a></h2><h3 id="_4-1-comite-de-manutencao-de-configuracoes" tabindex="-1">4.1 Comitê de Manutenção de Configurações <a class="header-anchor" href="#_4-1-comite-de-manutencao-de-configuracoes" aria-label="Permalink to &quot;4.1 Comitê de Manutenção de Configurações&quot;">​</a></h3><p>O Comitê de Manutenção de Configurações é a mais alta instituição de manutenção do sistema de documentos, composta por criadores de configurações experientes, especialistas em verificação lógica e representantes de usuários. Suas responsabilidades centrais incluem:</p><ul><li>Aprovar a estrutura geral e os planos de revisão importantes do sistema de documentos</li><li>Verificar alterações importantes de configurações, garantir consistência com as configurações centrais</li><li>Arbitrar disputas de configurações, fornecer explicações autorizadas</li><li>Organizar regularmente a autoverificação completa de consistência de configurações</li><li>Publicar atualizações de versão geral do sistema de documentos</li></ul><h3 id="_4-2-mantenedor-de-modulo" tabindex="-1">4.2 Mantenedor de Módulo <a class="header-anchor" href="#_4-2-mantenedor-de-modulo" aria-label="Permalink to &quot;4.2 Mantenedor de Módulo&quot;">​</a></h3><p>Cada módulo designa um mantenedor de módulo, responsável pela manutenção diária dos 10 documentos desse módulo. Suas responsabilidades incluem:</p><ul><li>Rastrear a consistência de configurações dos documentos dentro do módulo</li><li>Verificar solicitações de revisão de documentos dentro do módulo</li><li>Coordenar referências cruzadas entre documentos dentro do módulo</li><li>Coletar feedback e sugestões dos usuários sobre o conteúdo do módulo</li><li>Relatar regularmente o status de manutenção do módulo ao Comitê de Manutenção de Configurações</li></ul><h3 id="_4-3-criador-de-documentos" tabindex="-1">4.3 Criador de Documentos <a class="header-anchor" href="#_4-3-criador-de-documentos" aria-label="Permalink to &quot;4.3 Criador de Documentos&quot;">​</a></h3><p>Qualquer criador qualificado pode participar da criação e revisão de documentos. As responsabilidades do criador incluem:</p><ul><li>Criar ou revisar documentos seguindo as normas de formato</li><li>Garantir que o conteúdo criado passe na verificação da tabela de autoverificação de contradições de configurações</li><li>Anexar instruções de revisão detalhadas ao enviar a revisão</li><li>Cooperar com o trabalho de verificação dos mantenedores e do comitê</li></ul><h2 id="_5-processo-de-revisao" tabindex="-1">5. Processo de Revisão <a class="header-anchor" href="#_5-processo-de-revisao" aria-label="Permalink to &quot;5. Processo de Revisão&quot;">​</a></h2><h3 id="_5-1-processo-de-revisao-regular" tabindex="-1">5.1 Processo de Revisão Regular <a class="header-anchor" href="#_5-1-processo-de-revisao-regular" aria-label="Permalink to &quot;5.1 Processo de Revisão Regular&quot;">​</a></h3><ol><li><strong>Enviar solicitação</strong>: O criador envia uma solicitação de revisão ao mantenedor do módulo, incluindo o número do documento revisado, a descrição do conteúdo revisado e o motivo da revisão.</li><li><strong>Verificação do módulo</strong>: O mantenedor do módulo verifica o conteúdo revisado, com foco na verificação das normas de formato e da consistência dentro do módulo. Após a aprovação na verificação, envia ao Comitê de Manutenção de Configurações.</li><li><strong>Aprovação do comitê</strong>: O Comitê de Manutenção de Configurações realiza a aprovação final do conteúdo revisado, com foco na verificação da consistência entre módulos e da consistência das configurações centrais.</li><li><strong>Executar revisão</strong>: Após a aprovação, o mantenedor do módulo ou o criador original executa a revisão do documento.</li><li><strong>Atualizar versão</strong>: Após a conclusão da revisão, atualiza o número de versão do documento e registra no log de atualizações deste documento.</li><li><strong>Sincronização relacionada</strong>: Se o conteúdo revisado afetar outros documentos, os documentos relacionados devem ser revisados de forma sincronizada.</li></ol><h3 id="_5-2-processo-de-revisao-de-emergencia" tabindex="-1">5.2 Processo de Revisão de Emergência <a class="header-anchor" href="#_5-2-processo-de-revisao-de-emergencia" aria-label="Permalink to &quot;5.2 Processo de Revisão de Emergência&quot;">​</a></h3><p>Para situações de emergência em que contradições ou erros graves de configurações são descobertos, o processo de revisão de emergência pode ser iniciado:</p><ol><li><strong>Relatório de emergência</strong>: O descobridor relata imediatamente o problema ao Comitê de Manutenção de Configurações.</li><li><strong>Aprovação rápida</strong>: O comitê conclui a aprovação de emergência dentro de 24 horas e fornece o plano de revisão.</li><li><strong>Executar revisão</strong>: Designa uma pessoa específica para executar a revisão imediatamente.</li><li><strong>Registro posterior</strong>: Após a conclusão da revisão, complementa o registro da solicitação de revisão e da verificação.</li></ol><h3 id="_5-3-revisao-completa-regular" tabindex="-1">5.3 Revisão Completa Regular <a class="header-anchor" href="#_5-3-revisao-completa-regular" aria-label="Permalink to &quot;5.3 Revisão Completa Regular&quot;">​</a></h3><p>O Comitê de Manutenção de Configurações organiza uma revisão completa do sistema de documentos uma vez por ano, incluindo:</p><ul><li>Autoverificação completa de consistência de configurações</li><li>Processamento centralizado de feedback dos usuários</li><li>Unificação e atualização do sistema de terminologia</li><li>Atualização sincronizada de documentos de índice</li><li>Verificação e correção unificada do formato de documentos</li></ul><h2 id="_6-log-de-atualizacoes" tabindex="-1">6. Log de Atualizações <a class="header-anchor" href="#_6-log-de-atualizacoes" aria-label="Permalink to &quot;6. Log de Atualizações&quot;">​</a></h2><h3 id="v1-0-primeiro-lancamento-completo" tabindex="-1">v1.0 (Primeiro Lançamento Completo) <a class="header-anchor" href="#v1-0-primeiro-lancamento-completo" aria-label="Permalink to &quot;v1.0 (Primeiro Lançamento Completo)&quot;">​</a></h3><ul><li>Concluída a criação e publicação de todos os 100 documentos</li><li>Estabelecida a estrutura completa e as normas de formato do sistema de documentos</li><li>Concluída a cobertura de conteúdo dos dez módulos</li><li>Estabelecido o sistema de índice de apêndices (dicionário de terminologia, índice de sistemas, índice legal, crônica, catálogo de todas as raças, personagens e organizações, FAQ, tabela de autoverificação, sugestões de expansão, instruções de versão)</li></ul><h3 id="area-de-registro-de-atualizacoes-de-versoes-posteriores" tabindex="-1">Área de Registro de Atualizações de Versões Posteriores <a class="header-anchor" href="#area-de-registro-de-atualizacoes-de-versoes-posteriores" aria-label="Permalink to &quot;Área de Registro de Atualizações de Versões Posteriores&quot;">​</a></h3><p>(O conteúdo das atualizações de versões posteriores será adicionado aqui, incluindo número de versão, data de publicação, resumo do conteúdo principal das atualizações)</p><h2 id="_7-normas-de-referencia-e-referencia-cruzada-de-documentos" tabindex="-1">7. Normas de Referência e Referência Cruzada de Documentos <a class="header-anchor" href="#_7-normas-de-referencia-e-referencia-cruzada-de-documentos" aria-label="Permalink to &quot;7. Normas de Referência e Referência Cruzada de Documentos&quot;">​</a></h2><h3 id="_7-1-referencia-interna" tabindex="-1">7.1 Referência Interna <a class="header-anchor" href="#_7-1-referencia-interna" aria-label="Permalink to &quot;7.1 Referência Interna&quot;">​</a></h3><p>A referência cruzada entre documentos usa o formato &quot;número do documento-título do documento&quot;, por exemplo, &quot;consulte o Documento 84 &#39;Programa Geral do Protocolo Arqueológico&#39;&quot;. Ao fazer referência, deve-se garantir que o documento referenciado realmente exista e que o número e o título estejam corretos.</p><h3 id="_7-2-referencia-de-terminologia" tabindex="-1">7.2 Referência de Terminologia <a class="header-anchor" href="#_7-2-referencia-de-terminologia" aria-label="Permalink to &quot;7.2 Referência de Terminologia&quot;">​</a></h3><p>Ao usar um termo central pela primeira vez, pode-se indicar que se deve consultar o item correspondente no Documento 90 &quot;Dicionário de Terminologia&quot;. Não é necessário repetir a indicação ao usar o mesmo termo posteriormente.</p><h3 id="_7-3-referencia-externa" tabindex="-1">7.3 Referência Externa <a class="header-anchor" href="#_7-3-referencia-externa" aria-label="Permalink to &quot;7.3 Referência Externa&quot;">​</a></h3><p>Se for necessário referenciar materiais reais ou obras fictícias fora do sistema de configurações, deve-se indicar a fonte e explicar claramente que essa referência é um material de referência sob o princípio de &quot;baseado na realidade&quot;, não representando a adoção completa do conteúdo pelo sistema de configurações.</p><h2 id="_8-mecanismo-de-garantia-de-qualidade" tabindex="-1">8. Mecanismo de Garantia de Qualidade <a class="header-anchor" href="#_8-mecanismo-de-garantia-de-qualidade" aria-label="Permalink to &quot;8. Mecanismo de Garantia de Qualidade&quot;">​</a></h2><h3 id="_8-1-autoverificacao-de-contradicoes-de-configuracoes" tabindex="-1">8.1 Autoverificação de Contradições de Configurações <a class="header-anchor" href="#_8-1-autoverificacao-de-contradicoes-de-configuracoes" aria-label="Permalink to &quot;8.1 Autoverificação de Contradições de Configurações&quot;">​</a></h3><p>Todos os documentos recém-criados e revisados devem passar por todos os itens de verificação do Documento 97 &quot;Tabela de Autoverificação de Contradições de Configurações&quot;, incluindo mais de 40 verificações em três categorias: consistência das configurações centrais, consistência lógica entre módulos e normas de formato de documentos.</p><h3 id="_8-2-verificacao-cruzada" tabindex="-1">8.2 Verificação Cruzada <a class="header-anchor" href="#_8-2-verificacao-cruzada" aria-label="Permalink to &quot;8.2 Verificação Cruzada&quot;">​</a></h3><p>Cada documento deve passar pela verificação cruzada de pelo menos um outro criador antes do lançamento formal, com foco na verificação da consistência lógica entre módulos e da unificação da terminologia.</p><h3 id="_8-3-mecanismo-de-feedback-do-usuario" tabindex="-1">8.3 Mecanismo de Feedback do Usuário <a class="header-anchor" href="#_8-3-mecanismo-de-feedback-do-usuario" aria-label="Permalink to &quot;8.3 Mecanismo de Feedback do Usuário&quot;">​</a></h3><p>O sistema de documentos estabelece um canal de feedback do usuário, por meio do qual os usuários podem enviar feedback das seguintes maneiras:</p><ul><li>Relatar contradições de configurações e erros lógicos</li><li>Apresentar problemas de não unificação de terminologia</li><li>Sugerir complemento ou revisão de conteúdo específico</li><li>Indicar erros de formato e texto</li></ul><p>Todo o feedback é processado de forma classificada pelo mantenedor do módulo, e o feedback importante é submetido à deliberação do Comitê de Manutenção de Configurações.</p><h3 id="_8-4-relatorio-trimestral-de-consistencia" tabindex="-1">8.4 Relatório Trimestral de Consistência <a class="header-anchor" href="#_8-4-relatorio-trimestral-de-consistencia" aria-label="Permalink to &quot;8.4 Relatório Trimestral de Consistência&quot;">​</a></h3><p>O Comitê de Manutenção de Configurações publica um &quot;Relatório de Consistência de Configurações&quot; a cada trimestre, cujo conteúdo inclui:</p><ul><li>Contradições de configurações descobertas neste trimestre e status de processamento</li><li>Estatísticas de revisão de documentos neste trimestre</li><li>Progresso da unificação de terminologia</li><li>Status de processamento do feedback dos usuários</li><li>Plano de manutenção para o próximo trimestre</li></ul><h2 id="_9-armazenamento-e-distribuicao-de-documentos" tabindex="-1">9. Armazenamento e Distribuição de Documentos <a class="header-anchor" href="#_9-armazenamento-e-distribuicao-de-documentos" aria-label="Permalink to &quot;9. Armazenamento e Distribuição de Documentos&quot;">​</a></h2><h3 id="_9-1-formato-de-armazenamento" tabindex="-1">9.1 Formato de Armazenamento <a class="header-anchor" href="#_9-1-formato-de-armazenamento" aria-label="Permalink to &quot;9.1 Formato de Armazenamento&quot;">​</a></h3><p>Todos os documentos são armazenados no formato Markdown (.md), garantindo legibilidade entre plataformas e conveniência no gerenciamento de versão. Os documentos usam codificação UTF-8, suportando chinês e caracteres especiais.</p><h3 id="_9-2-estrutura-de-diretorios" tabindex="-1">9.2 Estrutura de Diretórios <a class="header-anchor" href="#_9-2-estrutura-de-diretorios" aria-label="Permalink to &quot;9.2 Estrutura de Diretórios&quot;">​</a></h3><p>Os documentos são armazenados de forma unificada no diretório <code>anchor-docs/</code>, com nomes de arquivo no formato <code>XX-título do documento.md</code>. O SPEC.md, como arquivo de normas, também é armazenado no mesmo diretório.</p><h3 id="_9-3-gerenciamento-de-versao" tabindex="-1">9.3 Gerenciamento de Versão <a class="header-anchor" href="#_9-3-gerenciamento-de-versao" aria-label="Permalink to &quot;9.3 Gerenciamento de Versão&quot;">​</a></h3><p>Recomenda-se usar sistemas de controle de versão como o Git para gerenciar as versões dos documentos, anexando uma mensagem de commit detalhada a cada envio de revisão, registrando o conteúdo e o motivo da revisão.</p><h3 id="_9-4-metodos-de-distribuicao" tabindex="-1">9.4 Métodos de Distribuição <a class="header-anchor" href="#_9-4-metodos-de-distribuicao" aria-label="Permalink to &quot;9.4 Métodos de Distribuição&quot;">​</a></h3><p>O sistema de documentos pode ser distribuído das seguintes maneiras:</p><ul><li>Empacotado como arquivo ZIP compactado para download</li><li>Implantado como site estático para navegação online</li><li>Convertido para formato PDF ou EPUB para leitura</li><li>Importado para sistemas de gerenciamento de conhecimento para gerenciamento estruturado</li></ul><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>As Instruções de Versão e Manutenção de Documentos são a &quot;constituição de gerenciamento&quot; do sistema de configurações da Civilização de Simbiose de Âncora. Elas estabelecem as regras de versão, a organização de manutenção, o processo de revisão, o mecanismo de garantia de qualidade e os métodos de armazenamento e distribuição do sistema de documentos, garantindo que esse enorme sistema de configurações, composto por 100 documentos, possa sempre manter ordem e consistência no processo de crescimento contínuo. Um bom sistema de configurações não precisa apenas de conteúdo excelente, mas também de um mecanismo de manutenção perfeito para garantir seu desenvolvimento saudável a longo prazo. Este documento é precisamente o portador central desse mecanismo.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>97-Tabela de Autoverificação de Contradições de Configurações</li><li>90-Dicionário de Terminologia</li><li>00-Visão Geral do Universo de Hengyuanzhou</li></ul>',77)])])}const f=o(d,[["render",s]]);export{p as __pageData,f as default};
